									WHERE A.EndpointSystemId = @DEPENDENT_SYSTEMID AND R.EndpointSystemId = @DEPENDENT_SYSTEMID AND RelatedObjectType='AG' and ActualObjectType='S' and ActualObjectCode IN(SELECT POSITION FROM @POSITIONS_TBL) AND RelatedObjectCode not in(SELECT TECHNICALROLE FROM @tblCRequestRole)
									
