								INSERT INTO @POSITIONS_TBL(POSITION)  EXEC USP_GETPARENTANDORGPOSITION @DEPENDENT_SYSTEMID,@TEMP_POS_CODE
					
								INSERT INTO @tblCRequestRole(POSITION,TechnicalRole,BUSINESSROLE,ENDPOINTNAME,EP_CODE)
								SELECT 
