							/***************************Parent position start***************************/
							INSERT INTO @POSITIONS_TBL(POSITION)  EXEC USP_GETPARENTANDORGPOSITION @endpointSystemId,@TEMP_POS_CODE
					
							INSERT INTO @tblCRequestRole(POSITION,TechnicalRole,BUSINESSROLE,ENDPOINTNAME,EP_CODE)
							SELECT 
							@positionText,RelatedObjectCode,ISNULL(M.ROLENAME,r.ROLE_DESC),@endpointsystem,@CURRENT_APPln
							FROM DI_SAP_SAPHRP1001 A INNER JOIN  DI_SAP_ROLEINFO R ON A.RelatedObjectCode = R.ROLE_CODE
							LEFT JOIN 
