							SELECT @positionText,[ROLE],ISNULL(M.ROLENAME,DESCR),@DEPENDENT_SYSTEM_NAME,@DEPENDENT_APPln from dbo.getRoleFromPosition(@DEPENDENT_SYSTEMID,@TEMP_POS_CODE) AS A
							LEFT JOIN 
